import { Platform } from "react-native";

import { useWebUpdateStore } from "@/store/use-web-update-store";

// dist/sw.js is generated by Workbox in `npm run build:web` (see workbox-config.js).
// It is skipped in development so cached bundles never hide code edits.
let isApplyingUpdate = false;

export function registerServiceWorker() {
  if (Platform.OS !== "web" || __DEV__ || !("serviceWorker" in navigator)) return;

  const { setWaitingWorker } = useWebUpdateStore.getState();

  // Only an update needs the banner. On the first install there is no
  // controller yet, and the new worker takes over without a reload.
  const trackWaiting = (registration: ServiceWorkerRegistration) => {
    if (registration.waiting && navigator.serviceWorker.controller) {
      setWaitingWorker(registration.waiting);
    }
  };

  const register = () => {
    navigator.serviceWorker
      .register("/sw.js")
      .then((registration) => {
        trackWaiting(registration);
        registration.addEventListener("updatefound", () => {
          const worker = registration.installing;
          worker?.addEventListener("statechange", () => {
            if (worker.state === "installed") trackWaiting(registration);
          });
        });

        // Installed PWAs resume instead of reloading, so check for a new
        // version whenever the app comes back to the foreground.
        document.addEventListener("visibilitychange", () => {
          if (document.visibilityState === "visible") void registration.update().catch(() => {});
        });
      })
      .catch(() => console.warn("Could not register the service worker."));
  };

  // Register after the page has loaded so it doesn't compete with the app bundle.
  if (document.readyState === "complete") register();
  else window.addEventListener("load", register, { once: true });

  // The new worker took over after the user asked for it; load the new version.
  navigator.serviceWorker.addEventListener("controllerchange", () => {
    if (isApplyingUpdate) window.location.reload();
  });
}

export function applyWebUpdate(worker: ServiceWorker) {
  isApplyingUpdate = true;
  // Workbox's generated worker listens for this message and activates.
  worker.postMessage({ type: "SKIP_WAITING" });
}
